function batchTransfer(address[] _to, uint _value) public {
    uint256 _sum;
    for (uint i = 0; i < _to.length; i++) {
        _sum = safeAdd(_sum, _value);
        balances[_to[i]] = safeAdd(balances[_to[i]], _value);
        Transfer(msg.sender, _to[i], _value);
    }
    return _sum;
}
